def validate_refund_input(order_id, amount_cents):
    order = get_order(order_id)  # your own DB
    if order is None:
        return f"No such order: {order_id}"
    if amount_cents <= 0:
        return "Amount must be positive."
    if amount_cents > order.paid_total_cents:
        return "Exceeds the order's paid total."
